function parseVector(raw){const s=raw.trim().replace(/−/g,'-').replace(/^\(/,'').replace(/\)$/,'');const parts=s.includes(';')?s.split(';'):s.split(',');if(parts.length<2||parts.length>3||parts.some(p=>!p.trim()))return null;const values=parts.map(parseAnswer);return values.every(Number.isFinite)?values:null}
function vectorModel(x=3,y=4){const length=Math.hypot(x,y),angle=length?Math.atan2(y,x)*180/Math.PI:null;return {x,y,length,angle}}
function vectorFigure(x=3,y=4){const m=vectorModel(x,y),px=150+x*12,py=120-y*12;return `<svg viewBox="0 0 300 240" role="img" aria-label="Вектор (${x};${y}), длина ${m.length.toFixed(2)}"><path d="M15 120H285M150 15V225" stroke="currentColor" opacity=".3"/><path d="M150 120H${px}V${py}" fill="none" stroke="currentColor" stroke-dasharray="4 4" opacity=".4"/><path class="vector-shaft" d="M150 120L${px} ${py}" stroke="currentColor" stroke-width="3"/>${lengthArrow(x,y,px,py)}<text x="160" y="140" fill="currentColor">O</text><text x="${Math.min(250,Math.max(10,px+8))}" y="${Math.max(15,py-8)}" fill="currentColor">a</text><text x="276" y="140" fill="currentColor">x</text><text x="160" y="20" fill="currentColor">y</text></svg>`}
function vectorsHTML(){return `<figure class="geometry-figure vector-lab"><div class="section-kicker">ВЕКТОР НА ПЛОСКОСТИ · МОДЕЛЬ</div><div class="vector-plot">${vectorFigure()}</div><label>Координата x <input type="range" min="-8" max="8" value="3" data-vector-x></label><label>Координата y <input type="range" min="-8" max="8" value="4" data-vector-y></label><p class="vector-result" aria-live="polite">a=(3;4), |a|=5. Направление: от O к отмеченному концу a.</p><small>Длина и направление меняются вместе с координатами. Для (0;0) направление не определено.</small></figure>`}
document.addEventListener('input',e=>{if(!e.target.matches('[data-vector-x],[data-vector-y]'))return;const host=e.target.closest('.vector-lab'),x=+host.querySelector('[data-vector-x]').value,y=+host.querySelector('[data-vector-y]').value,m=vectorModel(x,y);host.querySelector('.vector-plot').innerHTML=vectorFigure(x,y);host.querySelector('.vector-result').textContent=`a=(${x};${y}), |a|=√${x*x+y*y} ≈ ${m.length.toFixed(3)}. ${m.angle===null?'Нулевой вектор: направление и угол не определены.':'Угол от положительной оси x: '+m.angle.toFixed(1)+'°.'}`});

function lengthArrow(x,y,px,py){const l=Math.hypot(x,y);if(!l)return `<circle cx="150" cy="120" r="4" fill="currentColor"/>`;const ux=x/l,uy=-y/l;return `<path d="M${px} ${py} L${px-10*ux+5*uy} ${py-10*uy-5*ux} L${px-10*ux-5*uy} ${py-10*uy+5*ux}Z" fill="currentColor"/>`}
